  var innerSizingTS = $("#bannerSizingTS");

  var forceUnfixClassTS = "forceUnfixTS";

  var fixedTopTS = $(".fixedTopTS");
  var fixedBottomTS = $(".fixedBottomTS");
  var fixedLeftTS = $(".fixedLeftTS");
  var fixedRightTS = $(".fixedRightTS");

